-- 2026-10-03 · the admin users list carries is_house / hide_phone, and the members count leaves the test accounts out
-- (generated from the live definition by replacing two anchors)
CREATE OR REPLACE FUNCTION public.bk_admin_data(p_token text, p_country text DEFAULT NULL::text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$ declare uid uuid; sc text; al text[]; begin uid := bk_admin_uid(p_token); sc := bk_admin_scope(uid, p_country); al := bk_admin_allowed(uid); return json_build_object( 'me', (select json_build_object('id',id,'name',name,'family_name',family_name, 'permissions',coalesce(to_jsonb(permissions),'[]'::jsonb), 'is_super_admin',is_super_admin, 'admin_countries',coalesce(to_jsonb(admin_countries),'[]'::jsonb)) from users where id = uid), 'scope', sc, 'gx', (select coalesce((select jsonb_object_agg(key, value) from jsonb_each(coalesce(extras,'{}'::jsonb)) where key like 'notify\_%' or key like 'verify\_%' or key = 'intake_bot' or key like 'maintenance\_%'), '{}'::jsonb) from site_content where id = 1), 'stats', (select json_build_object( 'listings', (select count(*) from listings where bk_scope_ok(country_code,sc,al)), 'live', (select count(*) from listings where bk_scope_ok(country_code,sc,al) and status='live'), 'pending', (select count(*) from listings where bk_scope_ok(country_code,sc,al) and status='pending'), 'sold', (select count(*) from listings where bk_scope_ok(country_code,sc,al) and status in ('sold','rented')), 'expired', (select count(*) from listings where bk_scope_ok(country_code,sc,al) and status='expired'), 'green', (select count(*) from listings l where bk_scope_ok(l.country_code,sc,al) and (l.tabu='green' or exists (select 1 from deed_types d where d.country_code=l.country_code and d.code=l.tabu and d.is_strong))), 'users', (select count(*) from users where role <> 'admin' and not coalesce(is_house,false) and bk_scope_ok(country,sc,al)), 'photos', (select count(*) from listing_photos p join listings l on l.id=p.listing_id where bk_scope_ok(l.country_code,sc,al)), 'reviews', (select count(*) from reviews rv join users tu on tu.id = rv.target_user where bk_scope_ok(tu.country,sc,al)), 'openReports', (select count(*) from listing_reports r left join listings l on l.id=r.listing_id where not r.resolved and (l.id is null or bk_scope_ok(l.country_code,sc,al))), 'openFeedback', (select count(*) from feedback where not handled and (country_code is null or bk_scope_ok(country_code,sc,al))), 'week', (select count(*) from listings where bk_scope_ok(country_code,sc,al) and created_at > now() - interval '7 days'), 'value', (select coalesce(sum(price_usd),0) from listings where bk_scope_ok(country_code,sc,al) and status='live' and deal='sale'), 'by_country', coalesce((select json_object_agg(country_code, n) from (select coalesce(country_code,'SY') country_code, count(*) n from listings where bk_scope_ok(country_code,sc,al) group by 1) x), '{}'::json))), 'listings', coalesce((select json_agg(x) from ( select l.id, l.ref, l.status, l.deal, l.property_type, l.price_usd, l.area_m2, l.tabu, l.condition, l.contact_name, l.contact_phone, l.created_at, l.is_featured, l.country_code, g.name_ar as gov, a.name_ar as area, trim(coalesce(u.name,'')||' '||coalesce(u.family_name,'')) as poster_name, u.phone as poster_phone, u.id as poster_id, (select ag.name from agencies ag where ag.user_id = l.user_id and ag.status = 'approved' limit 1) as agency_name, (select count(*) from listing_photos p where p.listing_id=l.id) as photos, coalesce((select coalesce(nullif(p.thumb_url,''), p.url) from listing_photos p where p.listing_id=l.id and coalesce(p.kind,'photo')='photo' order by p.sort_order, p.id limit 1), (select nullif(p.thumb_url,'') from listing_photos p where p.listing_id=l.id and p.kind='video' and coalesce(p.thumb_url,'') <> '' order by p.sort_order, p.id limit 1)) as cover, (select d.source from intake_drafts d where d.listing_id=l.id order by d.id desc limit 1) as via from listings l join governorates g on g.id=l.governorate_id left join areas a on a.id=l.area_id left join users u on u.id=l.user_id where bk_scope_ok(l.country_code,sc,al) order by l.created_at desc limit 500) x), '[]'::json), 'users', coalesce((select json_agg(x) from ( select u.id, u.member_no, u.phone_verified, u.name, u.family_name, u.phone, u.role, u.account_type, u.level, u.blocked, u.skip_review, u.avatar_url, u.bio, u.created_at, u.country, coalesce(u.is_house,false) as is_house, coalesce(u.hide_phone,false) as hide_phone, (select count(*) from listings l where l.user_id=u.id) as listings, (select string_agg(distinct coalesce(l.country_code,'SY'), ',') from listings l where l.user_id=u.id) as countries, (select round(avg(stars)::numeric,1) from reviews where target_user=u.id) as rating from users u where u.role <> 'admin' and bk_scope_ok(u.country,sc,al) order by u.created_at desc limit 500) x), '[]'::json), 'reports', coalesce((select json_agg(x) from ( select r.id, r.listing_id, r.reason, r.note, r.resolved, r.admin_reply, r.priority, r.replied_at, r.created_at, l.ref as listing_ref, l.country_code, trim(coalesce(ru.name,'')||' '||coalesce(ru.family_name,'')) as reporter_name, ru.phone as reporter_phone, ru.id as reporter_id, coalesce((select json_agg(json_build_object('sender',m.sender,'body',m.body,'created_at',m.created_at) order by m.created_at) from message_followups m where m.kind='report' and m.ref_id=r.id), '[]'::json) as thread from listing_reports r left join listings l on l.id = r.listing_id left join users ru on ru.id = r.user_id where l.id is null or bk_scope_ok(l.country_code,sc,al) order by r.created_at desc limit 500) x), '[]'::json), 'feedback', coalesce((select json_agg(x) from ( select f.id, f.kind, f.body, f.handled, f.admin_reply, f.priority, f.replied_at, f.created_at, coalesce(trim(coalesce(fu.name,'')||' '||coalesce(fu.family_name,'')), f.name) as sender_name, coalesce(fu.phone, f.contact) as sender_contact, fu.id as sender_id, coalesce((select json_agg(json_build_object('sender',m.sender,'body',m.body,'created_at',m.created_at) order by m.created_at) from message_followups m where m.kind='feedback' and m.ref_id=f.id), '[]'::json) as thread, f.country_code from feedback f left join users fu on fu.id = f.user_id where f.country_code is null or bk_scope_ok(f.country_code,sc,al) order by f.created_at desc limit 500) x), '[]'::json)); end $function$
;
